-- ========================================================
-- COMSAN MEETING SYSTEM - SUPABASE DATABASE SETUP SCRIPT
-- วิธีใช้: คัดลอกโค้ดทั้งหมดนี้ไปวางในเมนู SQL Editor ใน Supabase แล้วกด RUN
-- ========================================================

-- 1. สร้างตารางเก็บสถานะห้องประชุม (Meeting State)
CREATE TABLE IF NOT EXISTS comsan_meeting_state (
  id TEXT PRIMARY KEY DEFAULT 'current',
  state JSONB NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. เปิดใช้งาน Row Level Security (RLS)
ALTER TABLE comsan_meeting_state ENABLE ROW LEVEL SECURITY;

-- 3. กำหนดนโยบายความปลอดภัย (อนุญาตให้อ่านและบันทึกข้อมูลผ่าน Public Anon Key)
DROP POLICY IF EXISTS "Allow public read access" ON comsan_meeting_state;
CREATE POLICY "Allow public read access" ON comsan_meeting_state
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public insert access" ON comsan_meeting_state;
CREATE POLICY "Allow public insert access" ON comsan_meeting_state
  FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public update access" ON comsan_meeting_state;
CREATE POLICY "Allow public update access" ON comsan_meeting_state
  FOR UPDATE USING (true);

-- 4. เปิดใช้งาน Realtime สำหรับตาราง comsan_meeting_state
ALTER PUBLICATION supabase_realtime ADD TABLE comsan_meeting_state;

